import gleam/list
import gleam/result
import gleam/string
import rabbit/artifacts
import rabbit/config
import rabbit/daemon/registry
import rabbit/domain
import rabbit/ffi
import rabbit/pi
import rabbit/proof
import rabbit/provider
import rabbit/workspace/casa
import simplifile

pub type WorkspaceProvisioner =
  fn(String, List(String), String) -> Result(domain.WorkspaceBinding, String)

pub fn run_with_provider(
  root root: String,
  prompt prompt: String,
  repos repos: List(String),
  provider_config provider_config: config.ProviderConfig,
  api_key api_key: String,
  provider call: provider.Provider,
) -> Result(domain.JobSummary, String) {
  run_with_provider_and_workspace(
    root: root,
    prompt: prompt,
    repos: repos,
    provider_config: provider_config,
    api_key: api_key,
    provider: call,
    workspace: casa.provision,
  )
}

pub fn run_with_provider_and_workspace(
  root root: String,
  prompt prompt: String,
  repos repos: List(String),
  provider_config provider_config: config.ProviderConfig,
  api_key api_key: String,
  provider call: provider.Provider,
  workspace provision_workspace: WorkspaceProvisioner,
) -> Result(domain.JobSummary, String) {
  case repos {
    [] -> Error("workspace_repositories_required")
    _ ->
      run_with_workspace(
        root,
        prompt,
        repos,
        provider_config,
        api_key,
        call,
        provision_workspace,
      )
  }
}

fn run_with_workspace(
  root: String,
  prompt: String,
  repos: List(String),
  provider_config: config.ProviderConfig,
  api_key: String,
  call: provider.Provider,
  provision_workspace: WorkspaceProvisioner,
) -> Result(domain.JobSummary, String) {
  let assert Ok(job) =
    registry.create_job(
      registry.new(),
      prompt: prompt,
      cwd: root,
      model: provider_config.model,
    )

  let paths =
    artifacts.create(root, job.id)
    |> result.map_error(fn(_) { "artifact_create_failed" })

  use paths <- result.try(paths)

  let provisioning =
    domain.JobSummary(
      ..job,
      state: domain.Running,
      phase: domain.ProvisioningWorkspace,
      artifact_dir: paths.job_dir,
      updated_at: ffi.timestamp(),
    )

  let _ = artifacts.write_summary(paths, provisioning)
  let _ =
    artifacts.append_event(
      paths,
      domain.JobStarted(at: provisioning.created_at, id: job.id),
    )

  use workspace <- result.try(
    provision_workspace(job.id, repos, root)
    |> result.map_error(fn(message) {
      let failed =
        domain.JobSummary(
          ..provisioning,
          state: domain.Failed,
          phase: domain.Complete,
          updated_at: ffi.timestamp(),
          last_error: "workspace_provision_failed:" <> message,
        )
      let _ = artifacts.write_summary(paths, failed)
      let _ =
        artifacts.append_event(
          paths,
          domain.JobFailed(
            at: failed.updated_at,
            reason: domain.WorkspaceProvisionFailed,
            message: message,
          ),
        )
      "workspace_provision_failed:" <> message
    }),
  )

  let started =
    domain.JobSummary(
      ..provisioning,
      cwd: workspace.path,
      phase: domain.CallingModel,
      workspace: workspace,
      updated_at: ffi.timestamp(),
    )

  let _ = artifacts.write_summary(paths, started)

  case
    pi.run_once(
      prompt: prompt,
      cwd: workspace.path,
      model: provider_config.model,
      api_key: api_key,
      paths: paths,
      provider: call,
    )
  {
    Ok(Nil) -> {
      let finished =
        domain.JobSummary(
          ..started,
          state: domain.Succeeded,
          phase: domain.Complete,
          updated_at: ffi.timestamp(),
        )
      let _ = artifacts.write_summary(paths, finished)
      let _ =
        artifacts.append_event(
          paths,
          domain.JobFinished(at: finished.updated_at, state: domain.Succeeded),
        )
      Ok(finished)
    }
    Error(error) -> {
      let message = provider_error_to_string(error)
      let failed =
        domain.JobSummary(
          ..started,
          state: domain.Failed,
          phase: domain.Complete,
          updated_at: ffi.timestamp(),
          last_error: message,
        )
      let _ = artifacts.write_summary(paths, failed)
      let _ =
        artifacts.append_event(
          paths,
          domain.JobFailed(
            at: failed.updated_at,
            reason: domain.ProviderRequestFailed,
            message: message,
          ),
        )
      Ok(failed)
    }
  }
}

pub fn status(root: String, id: String) -> Result(String, String) {
  simplifile.read(from: artifacts.paths(root, id).summary_json)
  |> result.map_error(fn(_) { "job_not_found:" <> id })
}

pub fn logs(root: String, id: String) -> Result(String, String) {
  simplifile.read(from: artifacts.paths(root, id).transcript_txt)
  |> result.map_error(fn(_) { "job_logs_not_found:" <> id })
}

pub fn proof(
  root: String,
  id: String,
  helper: String,
) -> Result(String, String) {
  proof.render(artifacts.paths(root, id), helper)
}

pub fn list(root: String) -> Result(String, String) {
  case simplifile.read_directory(at: root <> "/.rabbit/jobs") {
    Ok(ids) -> {
      let lines =
        ids
        |> list.sort(string.compare)
        |> string.join("\n")

      case lines {
        "" -> Ok("")
        _ -> Ok(lines <> "\n")
      }
    }
    Error(_) -> Ok("")
  }
}

fn provider_error_to_string(error: provider.Error) -> String {
  case error {
    provider.Configuration(message) ->
      "provider_configuration_failed:" <> message
    provider.RequestFailed(message) -> "provider_request_failed:" <> message
    provider.DecodeFailed(message) -> "provider_decode_failed:" <> message
  }
}

import gleam/result
import gleam/string
import rabbit/artifacts
import rabbit/domain
import rabbit/ffi
import rabbit/provider
import simplifile

pub fn system_prompt() -> String {
  [
    "You are a coding agent. Here are some very important rules that you must follow:",
    "",
    "General:",
    "- Be very precise and concise when writing code, comments, explanations, etc.",
    "- Use the `gh` CLI tool when querying PRs, issues, or other GitHub resources",
    "",
    "Coding:",
    "- When in doubt, always refer to the CONTRIBUTING.md file of the project",
    "- For drafting whole solutions, follow a 'Research, Plan, Implement' order of operations for completing the task.",
    "",
    "Pull requests (PRs):",
    "- When creating a pull request, look for the repository's PR template and follow it",
  ]
  |> string.join("\n")
  |> fn(prompt) { prompt <> "\n" }
}

pub fn run_once(
  prompt prompt: String,
  cwd cwd: String,
  model model: String,
  api_key api_key: String,
  paths paths: artifacts.Paths,
  provider call: provider.Provider,
) -> Result(Nil, provider.Error) {
  let at = ffi.timestamp()
  let _ =
    artifacts.append_event(
      paths,
      domain.ModelRequestStarted(at: at, model: model),
    )

  let _ = artifacts.append_transcript(paths, "cwd: " <> cwd <> "\n")
  use _ <- result.try(
    write_system_prompt(cwd)
    |> result.map_error(fn(_) {
      provider.Configuration("system_prompt_write_failed")
    }),
  )

  let request =
    provider.Request(prompt: prompt, cwd: cwd, model: model, api_key: api_key)

  case call(request) {
    Ok(response) -> {
      let _ = artifacts.append_transcript(paths, response.text <> "\n")
      let _ =
        artifacts.append_event(
          paths,
          domain.TranscriptAppended(at: ffi.timestamp(), text: response.text),
        )
      Ok(Nil)
    }
    Error(error) -> Error(error)
  }
}

fn write_system_prompt(cwd: String) -> Result(Nil, simplifile.FileError) {
  use _ <- result.try(require_existing_directory(cwd))
  let pi_dir = cwd <> "/pi/agents"
  use _ <- result.try(simplifile.create_directory_all(pi_dir))
  simplifile.write(to: pi_dir <> "/SYSTEM.md", contents: system_prompt())
}

fn require_existing_directory(
  path: String,
) -> Result(Nil, simplifile.FileError) {
  case simplifile.is_directory(path) {
    Ok(True) -> Ok(Nil)
    Ok(False) -> Error(simplifile.Enoent)
    Error(error) -> Error(error)
  }
}

import gleam/dynamic/decode
import gleam/json
import gleam/result
import gleam/string
import rabbit/domain
import rabbit/ffi

pub type CommandRunner =
  fn(String, List(String), String) -> Result(String, String)

pub fn workspace_name(job_id: String) -> String {
  "rabbit-" <> job_id
}

pub fn new_args(name: String, repos: List(String)) -> List(String) {
  ["new", name, string.join(repos, ",")]
}

pub fn inspect_args(name: String) -> List(String) {
  ["inspect", name]
}

pub fn provision(
  job_id: String,
  repos: List(String),
  cwd: String,
) -> Result(domain.WorkspaceBinding, String) {
  provision_with(ffi.run_command, job_id, repos, cwd)
}

pub fn provision_with(
  command_runner: CommandRunner,
  job_id: String,
  repos: List(String),
  cwd: String,
) -> Result(domain.WorkspaceBinding, String) {
  let name = workspace_name(job_id)

  use _ <- result.try(command_runner("casa", new_args(name, repos), cwd))
  use body <- result.try(command_runner("casa", inspect_args(name), cwd))

  decode_inspect(name, body)
}

pub fn decode_inspect(
  name: String,
  body: String,
) -> Result(domain.WorkspaceBinding, String) {
  let repository_decoder = {
    use directory <- decode.field("directory", decode.string)
    use source <- decode.field("source", decode.string)
    use path <- decode.field("path", decode.string)
    use exists <- decode.field("exists", decode.bool)
    decode.success(domain.RepositoryBinding(
      directory: directory,
      source: source,
      path: path,
      exists: exists,
    ))
  }

  let decoder = {
    use path <- decode.field("path", decode.string)
    use _metadata_path <- decode.field("metadata_path", decode.string)
    use _metadata_present <- decode.field("metadata_present", decode.bool)
    use repositories <- decode.field(
      "repositories",
      decode.list(of: repository_decoder),
    )
    decode.success(domain.WorkspaceBinding(
      manager: "casa",
      name: name,
      path: path,
      repositories: repositories,
    ))
  }

  json.parse(from: body, using: decoder)
  |> result.map_error(fn(_) { "workspace_inspect_failed" })
}

import gleam/list
import gleam/string
import simplifile

pub type ProviderConfig {
  ProviderConfig(name: String, model: String, api_key_env: String)
}

pub fn default_provider() -> ProviderConfig {
  ProviderConfig(
    name: "openrouter",
    model: "anthropic/claude-sonnet-4",
    api_key_env: "OPENROUTER_API_KEY",
  )
}

pub fn load_from_root(root: String) -> Result(ProviderConfig, Nil) {
  let project_config = root <> "/rabbit.toml"

  case simplifile.read(from: project_config) {
    Ok(contents) -> Ok(parse_provider(contents))
    Error(_) -> Ok(default_provider())
  }
}

pub fn parse_provider(contents: String) -> ProviderConfig {
  let lines = string.split(contents, "\n")
  let defaults = default_provider()

  ProviderConfig(
    name: value(lines, "name", defaults.name),
    model: value(lines, "model", defaults.model),
    api_key_env: value(lines, "api_key_env", defaults.api_key_env),
  )
}

fn value(lines: List(String), key: String, default: String) -> String {
  let found =
    lines
    |> list.find(fn(line) {
      line
      |> string.trim
      |> string.starts_with(key <> " = ")
    })

  case found {
    Ok(line) ->
      case string.split_once(line, "=") {
        Ok(parts) ->
          parts.1
          |> string.trim
          |> string.replace("\"", "")
        Error(_) -> default
      }
    Error(_) -> default
  }
}
